EXTRA = {  # 目录里的产品名、语言设置
"豆包":["豆包","Doubao","Doubao","Doubao","Doubao","Doubao","Doubao"],
"元宝":["元寶","Yuanbao","Yuanbao","Yuanbao","Yuanbao","Yuanbao","Yuanbao"],
"通义":["通義","Tongyi","Tongyi","Tongyi","Tongyi","Tongyi","Tongyi"],
"跟随系统":["跟隨系統","System","システムに合わせる","시스템 설정","Sistema","Système","System"],
"语言":["語言","Language","言語","언어","Idioma","Langue","Sprache"],
}
missing = [i for i in range(len(keys)) if i not in T]
assert not missing, missing
def sw(s):  # Swift 字符串字面量（\n 已经是转义形式）
    return '"' + s.replace('"', '\\"') + '"'
lines = ['// 自动生成：scripts/gen_translations.py —— 顺序：繁體中文, English, 日本語, 한국어, Español, Français, Deutsch',
         'enum Translations {', '    static let table: [String: [String]] = [']
for i, k in enumerate(keys):
    row = T[i]; assert len(row) == 7, i
    # 占位符数量检查
    n = k.count('%@')
    for t in row:
        assert t.count('%@') + sum(t.count(f'%{j}$@') for j in range(1, 6)) == n, (i, t)
    lines.append(f'        {sw(k)}: [' + ', '.join(sw(t) for t in row) + '],')
for k, row in EXTRA.items():
    lines.append(f'        {sw(k)}: [' + ', '.join(sw(t) for t in row) + '],')
lines += ['    ]', '}', '']
open(sys.argv[2], 'w', encoding='utf-8').write('\n'.join(lines))
print("写入", len(keys) + len(EXTRA), "条")
